//! 🛬️ Complete PNG entity reconstruction owns only admitted typed fields and refuses every orphan.
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteValue};
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind};
use super::{chunks::{Chunk,Native,Text},compression::{Block,Length,Stream,Token},rows::Rows,scanline::{Header,Row,Scanlines}};
type Result<T>=std::result::Result<T,ValueError>;
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn number<T:TryFrom<i64>>(row:&SqliteRow,column:usize)->Result<T>{T::try_from(row.integer(column)?).map_err(|_|invalid("PNG integer exceeds its intrinsic domain"))}
fn boolean(row:&SqliteRow,column:usize)->Result<bool>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("PNG boolean exceeds its intrinsic domain"))}}
fn field_rows(rows:&mut Rows<'_>,table:&str,parent:i64,control:&mut NativeDecodeControl<'_>)->Result<Vec<u32>>{let source=rows.group(table,parent,control)?;let mut values=control.allocate_vec(source.len())?;for row in source{values.push(number(row,3)?);control.step()?;}Ok(values)}
fn fixed(rows:&mut Rows<'_>,table:&str,key:i64,count:usize,control:&mut NativeDecodeControl<'_>)->Result<Vec<u32>>{let row=rows.take(table,key,control)?;let mut values=control.allocate_vec(count)?;for at in 1..=count{values.push(number(row,at)?);control.step()?;}Ok(values)}
fn octets(rows:&mut Rows<'_>,table:&str,parent:i64,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>>{let source=rows.group(table,parent,control)?;let mut values=control.allocate_vec(source.len())?;for row in source{values.push(number(row,3)?);control.step()?;}Ok(values)}
fn stream(rows:&mut Rows<'_>,id:i64,control:&mut NativeDecodeControl<'_>)->Result<Stream>{let row=rows.take("png_stream",id,control)?;if row.integer(1)?!=1{return Err(invalid("PNG stream document relation"))}let source=rows.group("png_deflate_block",id,control)?;let mut blocks=control.allocate_vec(source.len())?;for source in source{let id=source.rowid;let mut codes=control.allocate_vec(0)?;let values=rows.group("png_deflate_code",id,control)?;if !values.is_empty(){codes=control.allocate_vec(values.len())?;for row in values{let value:u8=number(row,3)?;if value>7{return Err(invalid("PNG code length exceeds three bits"))}codes.push(value);control.step()?;}}let values=rows.group("png_deflate_length",id,control)?;let mut lengths=control.allocate_vec(values.len())?;for row in values{lengths.push(Length{symbol:number(row,3)?,extra:number(row,4)?});control.step()?;}let values=rows.group("png_deflate_token",id,control)?;let mut tokens=control.allocate_vec(values.len())?;for row in values{let distance=match(row.values.get(5),row.values.get(6)){(Some(SqliteValue::Null),Some(SqliteValue::Null))=>None,(Some(SqliteValue::Integer(_)),Some(SqliteValue::Integer(_)))=>Some((number(row,5)?,number(row,6)?)),_=>return Err(invalid("PNG distance presence pair"))};tokens.push(Token{symbol:number(row,3)?,extra:number(row,4)?,distance});control.step()?;}blocks.push(Block{final_block:boolean(source,3)?,kind:number(source,4)?,alignment:number(source,5)?,hlit:number(source,6)?,hdist:number(source,7)?,hclen:number(source,8)?,codes,lengths,tokens});control.step()?;}Ok(Stream{cmf:number(row,2)?,flg:number(row,3)?,adler:number(row,4)?,padding:number(row,5)?,padding_bits:number(row,6)?,blocks})}
pub(super) fn reconstruct(database:&SqliteDatabase,control:&mut NativeDecodeControl<'_>)->Result<(String,Vec<u8>)>{control.scoped_stage(|control|{
 control.begin_stage(0)?;let mut rows=Rows::new(database,control)?;let document=rows.take("png_document",1,control)?;let schema=control.copy_text(document.text(1)?)?;match document.text(2)?{
  "literal"=>{let bytes=octets(&mut rows,"png_literal_octet",1,control)?;rows.finish(control)?;Ok((schema,bytes))},
  "native"=>{let source=rows.group("png_chunk",1,control)?;let mut chunks=control.allocate_vec(source.len())?;let(mut header,mut image,mut image_id)=(None,None,None);for source in source{let kind=control.borrow_text(source.text(3)?.as_bytes())?;let kind:[u8;4]=kind.as_bytes().try_into().map_err(|_|invalid("PNG chunk kind width"))?;let id=source.rowid;let mut chunk=Chunk{kind,fields:Vec::new(),octets:Vec::new(),text:None};match &kind{
   b"IHDR"=>{if header.is_some(){return Err(invalid("PNG duplicate header"))}let row=rows.take("png_ihdr",id,control)?;let value=Header{width:number(row,1)?,height:number(row,2)?,depth:number(row,3)?,color:number(row,4)?,compression:number(row,5)?,filter:number(row,6)?,interlace:number(row,7)?};chunk.fields=control.allocate_vec(7)?;chunk.fields.extend_from_slice(&[value.width,value.height,u32::from(value.depth),u32::from(value.color),u32::from(value.compression),u32::from(value.filter),u32::from(value.interlace)]);header=Some(value);},
   b"IDAT"=>{let row=rows.take("png_idat",id,control)?;let key=row.integer(1)?;if image_id.is_none(){image_id=Some(key);image=Some(stream(&mut rows,key,control)?);}else if image_id!=Some(key){return Err(invalid("PNG multiple image streams"))}chunk.fields=control.allocate_vec(1)?;chunk.fields.push(number(row,2)?);},
   b"IEND"=>{},b"PLTE"=>{let source=rows.group("png_palette",id,control)?;let count=source.len().checked_mul(3).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG palette backing extent"))?;chunk.fields=control.allocate_vec(count)?;for row in source{for column in 3..6{let value:u8=number(row,column)?;chunk.fields.push(u32::from(value));control.step()?;}}},
   b"tRNS"=>chunk.fields=field_rows(&mut rows,"png_transparency",id,control)?,b"bKGD"=>chunk.fields=field_rows(&mut rows,"png_background",id,control)?,b"gAMA"=>chunk.fields=fixed(&mut rows,"png_gamma",id,1,control)?,b"cHRM"=>chunk.fields=fixed(&mut rows,"png_chromaticity",id,8,control)?,b"sRGB"=>chunk.fields=fixed(&mut rows,"png_srgb",id,1,control)?,b"pHYs"=>chunk.fields=fixed(&mut rows,"png_physical",id,3,control)?,b"tIME"=>chunk.fields=fixed(&mut rows,"png_time",id,6,control)?,
   b"tEXt"|b"zTXt"|b"iTXt"=>{let row=rows.take("png_text",id,control)?;let compressed=boolean(row,5)?;let stream=match row.values.get(6){Some(SqliteValue::Null)=>None,Some(SqliteValue::Integer(id))=>Some(stream(&mut rows,*id,control)?),_=>return Err(invalid("PNG text stream reference"))};if compressed!=stream.is_some(){return Err(invalid("PNG text stream presence"))}chunk.text=Some(Text{keyword:control.copy_text(row.text(1)?)?,value:control.copy_text(row.text(2)?)?,language:control.copy_text(row.text(3)?)?,translated:control.copy_text(row.text(4)?)?,compressed,stream});},
   _=>chunk.octets=octets(&mut rows,"png_unknown_octet",id,control)?,
  }chunks.push(chunk);control.step()?;}
  let source=rows.group("png_scanline",1,control)?;let mut scanlines=control.allocate_vec(source.len())?;for row in source{let values=rows.group("png_sample",row.rowid,control)?;let mut samples=control.allocate_vec(values.len())?;for sample in values{samples.push(number(sample,3)?);control.step()?;}let(remainder,remainder_bits)=if rows.contains("png_packed_remainder",row.rowid){let row=rows.take("png_packed_remainder",row.rowid,control)?;(number(row,2)?,number(row,1)?)}else{(0,0)};scanlines.push(Row{pass:number(row,3)?,row:number(row,4)?,width:number(row,5)?,channels:number(row,6)?,depth:number(row,7)?,filter:number(row,8)?,samples,remainder,remainder_bits});control.step()?;}
  let tail=octets(&mut rows,"png_inflated_tail",1,control)?;rows.finish(control)?;let model=Native{header:header.ok_or_else(||invalid("PNG header owner absent"))?,chunks,image:image.ok_or_else(||invalid("PNG image compression owner absent"))?,scanlines:Scanlines{rows:scanlines,tail}};let bytes=super::chunks::encode(&model,control).map_err(super::syntax::Error::into_value_error)?;Ok((schema,bytes))},
  _=>Err(invalid("PNG document role")),
 }
})}
